import { useSelector } from "react-redux";

const CartSection = () => {
    const cart = useSelector(state => state.cart);

    console.log('This one: ',cart)
    return (
        <section>
            <h2>Cart</h2>
            {cart.length > 0 ? (
                <ul>
                    {cart.map(item => (
                        <li key={item.id}>
                            {item.name} - Quantity: {item.quantity}
                        </li>
                    ))}
                </ul>

            ) : (
                <p>Cart is empty</p>
            )}
        </section>
    )
}

export default CartSection
